@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><strong>Total</strong><span>@_allTasks.Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>To Do</strong><span>@GetColumn("To Do").Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>In Progress</strong><span>@GetColumn("In Progress").Count</span></div></div>
        <div class="col"><div class="card text-center p-2"><strong>Done</strong><span>@GetColumn("Done").Count</span></div></div>
        <div class="col"><div class="card text-center p-2 text-danger"><strong>Overdue</strong><span>@_allTasks.Count(t => t.DueDate < DateTime.Today)</span></div></div>
    </div>

    <!-- Search -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @foreach (var status in _columns)
        {
            var filtered = GetFilteredColumn(status);
            var colIndex = Array.IndexOf(_columns, status);

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@status</strong>
                        <span class="badge bg-secondary">@filtered.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2" style="min-height:200px; overflow-y:auto;">
                        @foreach (var task in filtered)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <small class="text-muted">@task.Assignee</small>
                                    <div class="d-flex align-items-center gap-2 mt-1">
                                        <span class="badge @PriorityClass(task.Priority)">@task.Priority</span>
                                        <small>@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="mt-2 d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            var prev = _columns[colIndex - 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTaskAsync(task.Id, prev)">← Move Left</button>
                                        }
                                        @if (colIndex < _columns.Length - 1)
                                        {
                                            var next = _columns[colIndex + 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTaskAsync(task.Id, next)">Move Right →</button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_addingToColumn == status)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2 d-flex flex-column gap-2">
                                    <input type="text" class="form-control form-control-sm" placeholder="Title"
                                           @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                           @bind="_newAssignee" />
                                    <select class="form-select form-select-sm" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary" @onclick="SaveNewTaskAsync">Save</button>
                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary w-100"
                                @onclick="() => StartAdd(status)">+ Add Task</button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumn(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumn(string status)
    {
        var items = _allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            items = items.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }
        return items.ToList();
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.First(t => t.Id == taskId);
            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => _addingToColumn = null;

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null) return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // CreateTaskAsync returns a task with default status; ensure it matches the target column.
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
                created = created with { Status = _addingToColumn };
            }
            _allTasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private static string PriorityClass(string priority) => priority switch
    {
        "High"   => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low"    => "bg-success",
        _        => "bg-secondary"
    };
}

